// Generates src/lib/api/generated.ts from the machine-readable contract owned by the backend:
//   packages/contracts/openapi.json  (regenerated by `python -m sparta openapi --out ...` in services/api)
// Run `npm run types:api` after the contract changes, then `npm run typecheck`.
import { mkdirSync, writeFileSync } from "node:fs";
import { dirname } from "node:path";
import { fileURLToPath } from "node:url";
import openapiTS, { astToString } from "openapi-typescript";

const contract = new URL("../../../packages/contracts/openapi.json", import.meta.url);
const output = fileURLToPath(new URL("../src/lib/api/generated.ts", import.meta.url));

// `defaultNonNullable: false`: fields that have server-side defaults are optional in request bodies. Response types are
// made fully required by the DeepRequired helper in types.ts (the API always serialises every field).
const ast = await openapiTS(contract, { alphabetize: true, defaultNonNullable: false });
const header = [
  "/**",
  " * GENERATED FILE: do not edit. Source: packages/contracts/openapi.json (owned by the API team).",
  " * Regenerate with `npm run types:api`. Hand-written helpers live in types.ts and enums.ts.",
  " */",
  "",
  "",
].join("\n");

mkdirSync(dirname(output), { recursive: true });
writeFileSync(output, header + astToString(ast));
console.log(`Wrote ${output}`);
